package mz.bam.seeky.android;
import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Standard RIFF cue/adtl chunks. PCM remains WAV and is never re-encoded. */
final class WavCues {
 static final int MAX=2000;
 static final class Cue {final long milliseconds;final String label;final int segment;Cue(long milliseconds,String label,int segment){if(milliseconds<0||segment<0)throw new IllegalArgumentException();this.milliseconds=milliseconds;this.label=AudioTitles.limit(AudioTitles.clean(label),128,512);this.segment=segment;}}
 static byte[] chunk(List<Cue> cues,int rate)throws IOException{if(cues.isEmpty()||rate<=0)return new byte[0];int count=Math.min(MAX,cues.size());ByteArrayOutputStream points=new ByteArrayOutputStream(),labels=new ByteArrayOutputStream();WavInfo.le(points,count);labels.write("adtl".getBytes(StandardCharsets.US_ASCII));for(int i=0;i<count;i++){Cue c=cues.get(i);long frame=c.milliseconds*rate/1000;if(frame>0xffffffffL)throw new IOException("Marcador fora do WAV.");WavInfo.le(points,i+1);WavInfo.le(points,(int)frame);points.write("data".getBytes(StandardCharsets.US_ASCII));WavInfo.le(points,0);WavInfo.le(points,0);WavInfo.le(points,(int)frame);byte[] value=c.label.getBytes(StandardCharsets.UTF_8);labels.write("labl".getBytes(StandardCharsets.US_ASCII));WavInfo.le(labels,value.length+5);WavInfo.le(labels,i+1);labels.write(value);labels.write(0);if(((value.length+5)&1)!=0)labels.write(0);}ByteArrayOutputStream out=new ByteArrayOutputStream();out.write("cue ".getBytes(StandardCharsets.US_ASCII));WavInfo.le(out,points.size());points.writeTo(out);out.write("LIST".getBytes(StandardCharsets.US_ASCII));WavInfo.le(out,labels.size());labels.writeTo(out);return out.toByteArray();}
 static long le(InputStream in)throws IOException{long n=0;for(int i=0;i<4;i++){int c=in.read();if(c<0)throw new EOFException();n|=(long)c<<(i*8);}return n;}
 static String tag(InputStream in)throws IOException{byte[] b=new byte[4];int at=0;while(at<4){int n=in.read(b,at,4-at);if(n<0)throw new EOFException();at+=n;}return new String(b,StandardCharsets.US_ASCII);}
 static void skip(InputStream in,long bytes)throws IOException{while(bytes>0){long n=in.skip(bytes);if(n>0)bytes-=n;else if(in.read()<0)throw new EOFException();else bytes--;}}
 static List<Cue> read(InputStream input)throws IOException{DataInputStream in=new DataInputStream(input);if(!tag(in).equals("RIFF"))return Collections.emptyList();long total=le(in);if(!tag(in).equals("WAVE"))return Collections.emptyList();long at=4;int rate=0;Map<Long,Long> points=new LinkedHashMap<>();Map<Long,String> labels=new HashMap<>();for(int chunks=0;chunks<4096&&at+8<=total;chunks++){String kind=tag(in);long size=le(in);at+=8;if(size>total-at)throw new IOException("Índice WAV inválido.");if(kind.equals("fmt ")&&size>=16){skip(in,4);rate=(int)le(in);skip(in,size-8);}else if(kind.equals("cue ")&&size>=4&&size<=MAX*24+4){long count=le(in);if(count>MAX||count*24+4>size)throw new IOException("Índice WAV inválido.");for(int i=0;i<count;i++){long id=le(in);skip(in,16);points.put(id,le(in));}skip(in,size-4-count*24);}else if(kind.equals("LIST")&&size>=4&&size<=2097152){byte[] bytes=new byte[(int)size];in.readFully(bytes);ByteArrayInputStream list=new ByteArrayInputStream(bytes);if(tag(list).equals("adtl")){while(list.available()>=8){String label=tag(list);long len=le(list);if(len>list.available())throw new IOException("Etiqueta WAV inválida.");if(label.equals("labl")&&len>=4&&len<=1024){long id=le(list);byte[] text=new byte[(int)len-4];if(list.read(text)!=text.length)throw new EOFException();int end=text.length;while(end>0&&text[end-1]==0)end--;labels.put(id,new String(text,0,end,StandardCharsets.UTF_8));}else skip(list,len);if((len&1)!=0)skip(list,1);}}}else skip(in,size);if((size&1)!=0)skip(in,1);at+=size+(size&1);}List<Cue> cues=new ArrayList<>();if(rate>0)for(Map.Entry<Long,Long> entry:points.entrySet())cues.add(new Cue(entry.getValue()*1000/rate,labels.getOrDefault(entry.getKey(),"Parte "+(cues.size()+1)),0));cues.sort((a,b)->Long.compare(a.milliseconds,b.milliseconds));return cues;}
 private WavCues(){}
}
